(()=>{const keys=['spotsense-gto-v3.3','spotsense-v3','riverlab-morandi-v3','pokerTrainer_v1','spotsense-legacy-backup-v1','spotsense-models-v1'],$=s=>document.querySelector(s),status=$('#backup-status'),read=k=>{try{return JSON.parse(SSStorage.get(k)||'null')}catch{return null}};function refresh(){const l=read(keys[0])||read(keys[1])||read(keys[2])||{},t=read('pokerTrainer_v1')||{},m=read('spotsense-models-v1')||{};$('#learn-count').textContent=Object.values(l.records||{}).filter(r=>r?.done).length+'/30';$('#hand-count').textContent=(t.stats?.totalHands||0).toLocaleString();$('#model-count').textContent=(m.math?.correct||0)+'/'+(m.math?.attempts||0)}refresh();addEventListener('storage',refresh);addEventListener('pageshow',refresh);$('#backup-export').onclick=()=>{const data=Object.fromEntries(keys.map(k=>[k,SSStorage.get(k)]).filter(x=>x[1]!==null)),url=URL.createObjectURL(new Blob([JSON.stringify({app:'SpotSense',version:2,data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SpotSense-backup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='已建立備份，請檢查下載提示。'};let pending=null;const dialog=$('#backup-dialog');$('#backup-import').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>15000000)throw Error('檔案超過15MB');const v=JSON.parse(await f.text());if(v.app!=='SpotSense'||![1,2].includes(v.version)||!v.data||typeof v.data!=='object')throw Error('不支援的格式');const entries=Object.entries(v.data);if(!entries.length)throw Error('沒有資料');for(const[k,val]of entries){if(!keys.includes(k)||typeof val!=='string')throw Error('不合法欄位');const obj=JSON.parse(val);if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('紀錄格式錯誤')}pending=entries;dialog.showModal()}catch(err){status.textContent='無法匯入：'+err.message}e.target.value=''};$('#backup-cancel').onclick=()=>{pending=null;dialog.close()};dialog.addEventListener('cancel',()=>pending=null);$('#backup-confirm').onclick=()=>{if(!pending)return;const old={};try{for(const[k]of pending)old[k]=SSStorage.get(k);for(const[k,val]of pending)if(!SSStorage.set(k,val))throw Error();status.textContent='已匯入紀錄。';refresh()}catch{for(const[k,val]of Object.entries(old))val===null?SSStorage.remove(k):SSStorage.set(k,val);status.textContent='匯入失敗，已嘗試還原，請保留備份。'}pending=null;dialog.close()}})();